CREATE DATABASE IF NOT EXISTS nikesh_print_hub; USE nikesh_print_hub;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stations(id INT AUTO_INCREMENT PRIMARY KEY,station_id VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS printers(id INT AUTO_INCREMENT PRIMARY KEY,printer_name VARCHAR(255) NOT NULL,station_id VARCHAR(80),is_default BOOLEAN DEFAULT FALSE,status VARCHAR(30) DEFAULT 'OFFLINE',last_activity DATETIME NULL);
CREATE TABLE IF NOT EXISTS print_jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id VARCHAR(100) UNIQUE NOT NULL,station_id VARCHAR(80) NOT NULL,printer_id INT NULL,file_name VARCHAR(255) NOT NULL,file_path TEXT NOT NULL,file_type VARCHAR(100),file_size BIGINT,page_count INT NULL,copies INT DEFAULT 1,paper_size VARCHAR(30),orientation VARCHAR(30),color_mode VARCHAR(50),duplex VARCHAR(30),custom_pages VARCHAR(255),status ENUM('QUEUED','PROCESSING','PRINTING','COMPLETED','FAILED','CANCELLED') DEFAULT 'QUEUED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS print_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id VARCHAR(100),status VARCHAR(30),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_tokens(id INT AUTO_INCREMENT PRIMARY KEY,station_id VARCHAR(80),token_hash VARCHAR(255),active BOOLEAN DEFAULT TRUE);
